#include "stdlib/blas/ext/base/ndarray/svander.h"
#include "stdlib/blas/ext/base/svander.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the mode.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_svander( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *out = arrays[ 1 ];

	float mode;
	stdlib_ndarray_get_float32( arrays[ 2 ], NULL, &mode );

	const CBLAS_INT M = stdlib_ndarray_dimension( out, 0 );
	const CBLAS_INT N = stdlib_ndarray_dimension( out, 1 );

	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	const CBLAS_INT strideOut1 = stdlib_ndarray_stride_elements( out, 0 );
	const CBLAS_INT strideOut2 = stdlib_ndarray_stride_elements( out, 1 );
	const CBLAS_INT offsetOut = stdlib_ndarray_offset_elements( out );

	const float *dataX = (const float *)stdlib_ndarray_data( x );
	float *dataOut = (float *)stdlib_ndarray_data( out );

	API_SUFFIX(stdlib_strided_svander_ndarray)( mode, M, N, dataX, strideX, offsetX, dataOut, strideOut1, strideOut2, offsetOut );
}
